3: function matchesField(value, rule) {
4:     if (Object.prototype.hasOwnProperty.call(rule, "expected") && value !== rule.expected) return false;
5:     if (rule.type === "array" && !Array.isArray(value)) return false;
6:     if (rule.type && rule.type !== "array" && typeof value !== rule.type) return false;
7:     if (rule.nonEmpty && (!Array.isArray(value) || value.length === 0)) return false;
8:     if (typeof rule.minLength === "number" && (typeof value !== "string" || value.length < rule.minLength)) return false;
9:     if (typeof rule.predicate === "function" && !rule.predicate(value)) return false;
10:     return true;
11: }
12: 
13: function fieldChecks(fields) {
14:     const groups = new Map();
15:     for (const [field, rule] of Object.entries(fields)) {
16:         const label = rule.label || field;
17:         if (!groups.has(label)) groups.set(label, []);
18:         groups.get(label).push({ field, rule });
19:     }
20:     return Object.fromEntries([...groups].map(([label, rules]) => [
21:         label,
22:         (response) => rules.every(({ field, rule }) => matchesField(response.json(field), rule)),
23:     ]));
24: }
25: 
26: export function checkFields(response, fields) {
27:     return check(response, fieldChecks(fields));
28: }
29: 
30: export function checkResponse(response, { status, fields = {} }) {
31:     return check(response, {
32:         ...(status ? { [status.label]: (r) => r.status === status.expected } : {}),
33:         ...fieldChecks(fields),
34:     });
35: }

